root=Path(__file__).parents[1]/'results';a=json.loads((root/'complex_schur_ellipse_L0649_L065_rho10_scout64.json').read_text());b=json.loads((root/'complex_schur_ellipse_L0649_L065_rho10_scout128odd.json').read_text());r=sorted(a['samples']+b['samples'],key=lambda x:x['theta']);z=[complex(x['L_real'],x['L_imag']) for x in r];p=[complex(x['strong_ldl_pivot_real'][17],x['strong_ldl_pivot_imag'][17]) for x in r];sec=max(abs((p[(i+1)%128]-p[i])/(z[(i+1)%128]-z[i])) for i in range(128));half=max(abs(z[(i+1)%128]-z[i]) for i in range(128))/2;sample=max(abs(x) for x in p);bound=sample+4*sec*half;out={'schema':'marici.voevodsky.gate3-E10-pivot17-128.v1','sampled_max':sample,'maximum_secant_derivative':sec,'half_chord':half,'adopted_derivative_safety_factor':4,'conditional_full_bound':bound,'required_by_E8_transfer':1.9e-5,'passed_conditionally':bound<1.9e-5,'passed':False,'remaining':'direct derivative enclosure at four times secant bound','rh_proved':False};pout=root/'gate3_E10_pivot17_128.json';pout.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));assert out['passed_conditionally']
